import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    d = [int(data[1 + 2 * i]) for i in range(n)]
    w = [int(data[2 + 2 * i]) for i in range(n)]
    stack = []
    for i in range(n):
        alive = True
        if d[i] == -1:
            while stack and d[stack[-1]] == 1:
                top = stack[-1]
                if w[top] < w[i]:
                    stack.pop()
                elif w[top] == w[i]:
                    stack.pop()
                    alive = False
                    break
                else:
                    alive = False
                    break
        if alive:
            stack.append(i)
    print(' '.join(map(str, stack)) if stack else -1)

